#include <stdlib.h>
typedef struct{int*a,n;int*b,m;}MedianFinder;static void upmax(int*a,int i){while(i){int p=(i-1)/2;if(a[p]>=a[i])break;int t=a[p];a[p]=a[i];a[i]=t;i=p;}}static void upmin(int*a,int i){while(i){int p=(i-1)/2;if(a[p]<=a[i])break;int t=a[p];a[p]=a[i];a[i]=t;i=p;}}static int popmax(int*a,int*n){int r=a[0];a[0]=a[--*n];for(int i=0;;){int l=2*i+1,rn=l+1,b=i;if(l<*n&&a[l]>a[b])b=l;if(rn<*n&&a[rn]>a[b])b=rn;if(b==i)break;int t=a[i];a[i]=a[b];a[b]=t;i=b;}return r;}static int popmin(int*a,int*n){int r=a[0];a[0]=a[--*n];for(int i=0;;){int l=2*i+1,rn=l+1,b=i;if(l<*n&&a[l]<a[b])b=l;if(rn<*n&&a[rn]<a[b])b=rn;if(b==i)break;int t=a[i];a[i]=a[b];a[b]=t;i=b;}return r;}MedianFinder* medianFinderCreate(){MedianFinder*x=calloc(1,sizeof(*x));x->a=malloc(50000*sizeof(int));x->b=malloc(50000*sizeof(int));return x;}void medianFinderAddNum(MedianFinder*x,int v){if(!x->n||v<=x->a[0]){x->a[x->n]=v;upmax(x->a,x->n++);}else{x->b[x->m]=v;upmin(x->b,x->m++);}if(x->n>x->m+1){int z=popmax(x->a,&x->n);x->b[x->m]=z;upmin(x->b,x->m++);}else if(x->m>x->n){int z=popmin(x->b,&x->m);x->a[x->n]=z;upmax(x->a,x->n++);}}double medianFinderFindMedian(MedianFinder*x){return x->n==x->m?((double)x->a[0]+x->b[0])/2:x->a[0];}void medianFinderFree(MedianFinder*x){free(x->a);free(x->b);free(x);}
